#include "mobile_inventory_adoption.hpp"
#include "movement_exact_detail.hpp"
#include "resident/storage/common_store.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {using namespace movement_detail;namespace {
SourceRef definition_ref(const StableId& id){return {"travel","authored_mobile_container",id};}
SourceRef initial_ref(const StableId& id){return {"travel","authored_mobile_container_placement",id};}
bool includes(const std::vector<StableId>& values,const StableId& id){return std::find(values.begin(),values.end(),id)!=values.end();}
std::size_t source_order(const CommonStore& common,const SourceRef& source){std::size_t n=0;for(const auto& row:common.state().facts.rows()){if(row.first==source.id){if(row.second.domain!=source.domain||row.second.kind!=source.kind)fail("MobileInventoryActualSourceHeaderRequired",source.id);return n;}++n;}fail("MobileInventoryActualSourceHeaderRequired",source.id);}
const MobileInventoryDefinition& definition(const CommonCatalog& common,const TravelCatalog& travel,const StableId& inventory){const MobileInventoryDefinition* result=nullptr;for(const auto& row:travel.mobile_inventory_definitions.rows())if(row.second.inventory_id==inventory){if(result)fail("DuplicateMobileInventoryDefinition",inventory);result=&row.second;}if(!result||result->id.empty()||result->version<1||result->container_maximum_weight<1||!common.required_inventories.find(inventory))fail("AuthoredMobileInventoryRequired",inventory);return *result;}
MovementAnchor site_anchor(const CommonCatalog& common,const TravelCatalog& travel,const StableId& site){if(const auto* place=common.places.find(site))return OriginalMovementAnchor{SettlementLocation{place->settlement_id,place->id},{"common_catalog","place",site}};const auto* settlement=travel.settlements.find(site);if(!settlement||!common.places.find(settlement->entry_place))fail("AuthoredMobileInventorySiteRequired",site);return OriginalMovementAnchor{SettlementLocation{site,settlement->entry_place},{"travel_catalog","settlement",site}};}
struct PlacementRead {const MobileInventoryDefinition* original=nullptr;MomentOwnerSource source;MovementAnchor anchor;std::optional<StableId> carrying_unit;StableId stationary_site;};
// 两个真实业务消费点共用缺源门；未选编组的静置箱不需要伪造业务 provider。
const TransportRegistrationBusinessRead& original_business(
    const MobileInventoryAdoptionContext& context, const StableId& actual_source) {
 if(!context.original_business)
  fail("MobileInventoryOriginalBusinessRequired",actual_source);
 return *context.original_business;
}
// Container moves are only the existing actual registration/release sources.
// The ordinal below is a hot causal cut, never persisted as a revision.
PlacementRead read_before(const MobileInventoryAdoptionContext& c,const StableId& inventory,const std::optional<SourceRef>& cut,const WorldMoment& at,bool general_observation=false){
 if(cut&&!general_observation&&(cut->domain!="local_economy"||cut->kind!="household_purchase_planned"))fail("MobileInventoryOriginalPlanSourceRequired",cut->id);
 const auto cut_order=cut?source_order(c.common,*cut):c.common.state().facts.size();take(encode_world_moment(at,c.budget));if(take(compare_world_moments(at,take(c.clock.read_current_moment()),c.budget))>0)fail("MobileInventoryPlanInFuture",cut?cut->id:StableId{});
 const auto& original=definition(c.common_catalog,c.travel_catalog,inventory);if(take(compare_world_moments(original.initialized_at,at,c.budget))>0)fail("MobileInventoryNotYetInstalled",inventory);
 if(!c.common.inventory(inventory))fail("MobileInventoryOriginalInventoryMissing",inventory);
 struct Event{std::size_t order;WorldMoment at;const TransportRegistrationSource* registration=nullptr;const TransportUnitReleaseSource* release=nullptr;};
 std::vector<Event> events;
 for(const auto& row:c.registrations.registrations.rows())if(includes(row.second.accepted_scope.inventory_ids,inventory)){const auto& r=row.second;const SourceRef source{"travel","transport_registration",r.id};const auto order=source_order(c.common,source);if(order<cut_order){if(take(compare_world_moments(r.occurred_at,at,c.budget))>0)fail("MobileInventoryCausalMomentMismatch",r.id);events.push_back({order,r.occurred_at,&r,nullptr});}else if(take(compare_world_moments(r.occurred_at,at,c.budget))<0)fail("MobileInventoryOmittedEarlierMovement",r.id);}
 for(const auto& row:c.registrations.releases.rows())if(includes(row.second.released_composition.inventory_ids,inventory)){const auto& r=row.second;const SourceRef source{"travel","transport_release",r.id};const auto order=source_order(c.common,source);if(order<cut_order){if(take(compare_world_moments(r.occurred_at,at,c.budget))>0)fail("MobileInventoryCausalMomentMismatch",r.id);events.push_back({order,r.occurred_at,nullptr,&r});}else if(take(compare_world_moments(r.occurred_at,at,c.budget))<0)fail("MobileInventoryOmittedEarlierMovement",r.id);}
 std::sort(events.begin(),events.end(),[](const auto& a,const auto& b){return a.order<b.order;});
 PlacementRead out{&original,{initial_ref(original.id),1},site_anchor(c.common_catalog,c.travel_catalog,original.initial_site_id),{},original.initial_site_id};std::optional<StableId> carrying_unit;WorldMoment last=original.initialized_at;
 for(const auto& event:events){if(take(compare_world_moments(event.at,last,c.budget))<0)fail("MobileInventoryMovementTimeReversed",inventory);last=event.at;
  if(event.registration){const auto& r=*event.registration;if(carrying_unit)fail("MobileInventoryDoubleCarrier",inventory);const auto* unit=c.carriers.transport_units.find(r.transport_unit_id);if(!unit||!same_source(unit->registration_source_ref,{"travel","transport_registration",r.id}))fail("MobileInventoryRegistrationBacklinkRequired",r.id);take(original_business(c,r.id).validate_registration_authority(r.accepted_scope));if(!take(same_actual_movement_position(out.anchor,r.departure_anchor,c.budget)))fail("MobileInventoryRegistrationTeleport",r.id);carrying_unit=r.transport_unit_id;out.source={{"travel","transport_registration",r.id},1};out.stationary_site.clear();
  }else{const auto& r=*event.release;if(!carrying_unit||*carrying_unit!=r.transport_unit_id||r.released_composition.transport_unit_id!=r.transport_unit_id)fail("MobileInventoryReleaseWithoutCarrier",r.id);take(original_business(c,r.id).validate_transport_handover(r,r.released_composition));const auto expected=site_anchor(c.common_catalog,c.travel_catalog,r.handover_site_id);if(!take(same_actual_movement_position(expected,r.actual_anchor,c.budget)))fail("MobileInventoryReleaseAnchorMismatch",r.id);out.source={{"travel","transport_release",r.id},1};out.anchor=r.actual_anchor;out.stationary_site=r.handover_site_id;carrying_unit.reset();}
 }
 if(carrying_unit&&cut&&!general_observation)fail("MobileInventoryAlreadyCarried",inventory);out.carrying_unit=carrying_unit;return out;
}
MobileInventoryAdoptionView adoption(const StableId& inventory,const PlacementRead& read,const WorldMoment& at){return {inventory,{}, {definition_ref(read.original->id),1},read.source,{definition_ref(read.original->id),1},at};}
bool equal_source(const MomentOwnerSource& a,const MomentOwnerSource& b){return a.source_schema==b.source_schema&&same_source(a.source_ref,b.source_ref);}
void equal_view(const MobileInventoryAdoptionView& a,const MobileInventoryAdoptionView& b,ExactArithmeticBudget budget){if(a.inventory_id!=b.inventory_id||a.vehicle_ref!=b.vehicle_ref||!equal_source(a.original_container_source,b.original_container_source)||!equal_source(a.spatial_source,b.spatial_source)||!equal_source(a.capacity_source,b.capacity_source)||!same_moment(a.adopted_at,b.adopted_at,budget))fail("MobileInventoryAdoptionMismatch",a.inventory_id);}
}
Status validate_mobile_inventory_definitions(const CommonCatalog& common,const TravelCatalog& travel){return status([&]{std::set<StableId> inventories;for(const auto& row:travel.mobile_inventory_definitions.rows()){const auto& d=row.second;if(row.first!=d.id||!inventories.insert(d.inventory_id).second)fail("InvalidMobileInventoryDefinition",row.first);definition(common,travel,d.inventory_id);site_anchor(common,travel,d.initial_site_id);take(encode_world_moment(d.initialized_at));const auto* original=common.required_inventories.find(d.inventory_id);if(original->owner.kind!=Owner::Kind::household)fail("UnsupportedMobileInventoryInitialOwner",d.inventory_id);}});}
Status initialize_mobile_inventory_bindings_in_candidate(const CommonStore& common,const CommonCatalog& catalog,const TravelCatalog& travel,SpatialCarrierState& state,const TransportRegistrationState& registrations,const CurrentMomentRead& clock){return status([&]{take(validate_mobile_inventory_definitions(catalog,travel));if(!registrations.registrations.empty()||!registrations.releases.empty()||!state.journeys.empty())fail("MobileInventoryInitialConstructionRequired");const auto now=take(clock.read_current_moment());for(const auto& row:travel.mobile_inventory_definitions.rows()){const auto& d=row.second;if(!same_moment(now,d.initialized_at)||state.inventory_bindings.find(d.inventory_id)||!common.inventory(d.inventory_id))fail("MobileInventoryInitialConstructionRequired",d.inventory_id);for(const auto& actor:common.state().actors.rows())if(actor.second.inventory_id==d.inventory_id)fail("MobileInventoryAlreadyActorContainer",d.inventory_id);}for(const auto& row:travel.mobile_inventory_definitions.rows()){const auto& d=row.second;state.inventory_bindings.set(d.inventory_id,{d.inventory_id,d.initial_site_id,initial_ref(d.id),0});}});}
Status validate_mobile_inventory_bindings(const MobileInventoryAdoptionContext& c){return status([&]{take(validate_mobile_inventory_definitions(c.common_catalog,c.travel_catalog));const auto now=take(c.clock.read_current_moment());for(const auto& row:c.travel_catalog.mobile_inventory_definitions.rows()){const auto& d=row.second;const auto actual=read_before(c,d.inventory_id,{},now);const auto* current=c.carriers.inventory_bindings.find(d.inventory_id);if(!current||!same_source(current->source_ref,actual.source.source_ref))fail("MobileInventoryCurrentBindingMismatch",d.inventory_id);if(actual.carrying_unit){const auto* carrier=std::get_if<SpatialCarrierRef>(&current->placement);const auto* transport=carrier?std::get_if<TransportUnitCarrierRef>(carrier):nullptr;const auto* unit=c.carriers.transport_units.find(*actual.carrying_unit);if(!transport||!unit||transport->transport_unit_ref.transport_unit_id!=*actual.carrying_unit||unit->state==TransportUnitLifecycle::dissolved||!includes(unit->inventory_ids,d.inventory_id))fail("MobileInventoryCurrentCarrierMismatch",d.inventory_id);take(c.spatial_sources.verify_registration_source(*unit));}else{const auto* site=std::get_if<StableId>(&current->placement);if(!site||*site!=actual.stationary_site)fail("MobileInventoryCurrentSiteMismatch",d.inventory_id);}const auto weight=take(c.common.inventory_weight(d.inventory_id));if(weight>d.container_maximum_weight)fail("MobileInventoryContainerOverloaded",d.inventory_id);}});}
Outcome<MobileInventoryAdoptionView> read_mobile_inventory_adoption_before_source(const MobileInventoryAdoptionContext& c,const StableId& inventory,const SourceRef& plan,const WorldMoment& at){return guard<MobileInventoryAdoptionView>([&]{take(validate_mobile_inventory_definitions(c.common_catalog,c.travel_catalog));return adoption(inventory,read_before(c,inventory,plan,at),at);});}
Outcome<MobileInventoryAdoptionView> capture_mobile_inventory_adoption(const MobileInventoryAdoptionContext& c,const StableId& inventory,const SourceRef& plan,const WorldMoment& at){return guard<MobileInventoryAdoptionView>([&]{if(!same_moment(at,take(c.clock.read_current_moment()),c.budget))fail("MobileInventoryActualAdoptionMomentRequired",inventory);auto actual=read_before(c,inventory,plan,at);const auto* binding=c.carriers.inventory_bindings.find(inventory);if(!binding||!std::holds_alternative<StableId>(binding->placement)||!same_source(binding->source_ref,actual.source.source_ref))fail("MobileInventoryCurrentBindingMismatch",inventory);const auto current=take(read_inventory_spatial_anchor(c.common,c.carriers,c.movement,c.spatial_sources,inventory,c.budget));if(!take(same_actual_movement_position(current,actual.anchor,c.budget)))fail("MobileInventoryCurrentAnchorMismatch",inventory);return adoption(inventory,actual,at);});}
Status validate_mobile_inventory_adoption(const MobileInventoryAdoptionContext& c,const MobileInventoryAdoptionView& value,const SourceRef& plan,const WorldMoment& at){return status([&]{equal_view(value,take(read_mobile_inventory_adoption_before_source(c,value.inventory_id,plan,at)),c.budget);});}
Outcome<MovementAnchor> read_mobile_inventory_adoption_anchor(const MobileInventoryAdoptionContext& c,const MobileInventoryAdoptionView& value,const SourceRef& plan,const WorldMoment& at){return guard<MovementAnchor>([&]{auto read=read_before(c,value.inventory_id,plan,at);equal_view(value,adoption(value.inventory_id,read,at),c.budget);return read.anchor;});}
Outcome<MobileInventoryBindingHistory> read_mobile_inventory_binding_before_source(const MobileInventoryAdoptionContext& c,const StableId& inventory,const SourceRef& observation,const WorldMoment& at){return guard<MobileInventoryBindingHistory>([&]{take(validate_mobile_inventory_definitions(c.common_catalog,c.travel_catalog));auto actual=read_before(c,inventory,observation,at,true);MobileInventoryBindingHistory out{inventory,actual.anchor,actual.source,{}};if(actual.carrying_unit){const auto* unit=c.carriers.transport_units.find(*actual.carrying_unit);if(!unit)fail("MobileInventoryRegistrationBacklinkRequired",inventory);out.carrying_unit=TransportUnitRef{unit->subject,unit->transport_unit_id};}return out;});}
Outcome<Integer> read_mobile_container_maximum_weight(const CommonCatalog& common,const TravelCatalog& travel,const MomentOwnerSource& source){return guard<Integer>([&]{const auto* d=source.source_schema==1&&source.source_ref.domain=="travel"&&source.source_ref.kind=="authored_mobile_container"?travel.mobile_inventory_definitions.find(source.source_ref.id):nullptr;if(!d)fail("MobileInventoryCapacitySourceRequired",source.source_ref.id);definition(common,travel,d->inventory_id);return d->container_maximum_weight;});}
}
